function formatPricePerUnit(price) {
  if (price === 0 || !Number.isFinite(price)) return "0";
  let str;
  if (price < 1e-3) {
    str = price.toFixed(5);
  } else if (price < 0.01) {
    str = price.toFixed(4);
  } else if (price < 0.1) {
    str = price.toFixed(3);
  } else {
    str = price.toFixed(2);
  }
  if (str.includes(".")) {
    str = str.replace(/\.?0+$/, "");
  }
  return str || "0";
}
