function setupCustomFlowPipeline(bot2, opts) {
  const steps = opts.flowConfig || [];
  const entryStep = steps.find((s) => s.triggerType === "entry") || steps[0];
  const renderStep = async (ctx, step, isEdit = false) => {
    const inlineButtons = (step.buttons || []).map((b) => {
      if (b.action === "open_url" && b.url) {
        return [import_telegraf5.Markup.button.url(b.label, b.url)];
      }
      return [import_telegraf5.Markup.button.callback(b.label, `flow_step:${b.targetStepId || step.id}`)];
    });
    const markup = inlineButtons.length > 0 ? import_telegraf5.Markup.inlineKeyboard(inlineButtons) : void 0;
    const name2 = ctx.from?.first_name || "\u0414\u0440\u0443\u0433";
    const text = step.messageText.replace(/{userName}/g, escapeHtml2(name2)).replace(/{siteName}/g, escapeHtml2(opts.botName));
    if (isEdit) {
      try {
        return await ctx.editMessageText(text, { parse_mode: "HTML", ...markup });
      } catch {
      }
    }
    return ctx.reply(text, { parse_mode: "HTML", ...markup });
  };
  bot2.start(async (ctx) => {
    if (entryStep) {
      return renderStep(ctx, entryStep, false);
    }
    return ctx.reply(opts.welcomeMessage || "\u{1F44B} \u0414\u043E\u0431\u0440\u043E \u043F\u043E\u0436\u0430\u043B\u043E\u0432\u0430\u0442\u044C!");
  });
  bot2.action(/^flow_step:(.+)$/, async (ctx) => {
    await ctx.answerCbQuery().catch(() => {
    });
    if (!ctx.match) return;
    const targetStepId = ctx.match[1];
    const targetStep = steps.find((s) => s.id === targetStepId);
    if (targetStep) {
      return renderStep(ctx, targetStep, true);
    }
  });
  bot2.on("text", async (ctx) => {
    const text = ctx.message.text.trim();
    const matchedStep = steps.find((s) => s.triggerType === "text" && s.triggerValue.toLowerCase() === text.toLowerCase());
    if (matchedStep) {
      return renderStep(ctx, matchedStep, false);
    }
  });
}
